import{_ as s,H as n,f as t,i as a}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"03 | 协议实战（上）：高德地图+MiniMax语音开发私域旅游小助手","description":"","frontmatter":{},"headers":[{"level":2,"title":"私域旅游小助手开发流程","slug":"私域旅游小助手开发流程","link":"#私域旅游小助手开发流程","children":[]},{"level":2,"title":"使用高德开放平台的地图 MCP 服务","slug":"使用高德开放平台的地图-mcp-服务","link":"#使用高德开放平台的地图-mcp-服务","children":[{"level":3,"title":"登录高德开放平台","slug":"登录高德开放平台","link":"#登录高德开放平台","children":[]},{"level":3,"title":"注册为高德开放平台开发者","slug":"注册为高德开放平台开发者","link":"#注册为高德开放平台开发者","children":[]},{"level":3,"title":"获取高德服务密钥","slug":"获取高德服务密钥","link":"#获取高德服务密钥","children":[]},{"level":3,"title":"在 Cursor 中配置高德 MCP","slug":"在-cursor-中配置高德-mcp","link":"#在-cursor-中配置高德-mcp","children":[]}]},{"level":2,"title":"使用 MiniMax 大模型的语音服务","slug":"使用-minimax-大模型的语音服务","link":"#使用-minimax-大模型的语音服务","children":[{"level":3,"title":"注册 Minimax 开放平台","slug":"注册-minimax-开放平台","link":"#注册-minimax-开放平台","children":[]},{"level":3,"title":"在 ModelScope 平台部署 Minimax sse","slug":"在-modelscope-平台部署-minimax-sse","link":"#在-modelscope-平台部署-minimax-sse","children":[]},{"level":3,"title":"在 Cursor 中配置 Minimax MCP","slug":"在-cursor-中配置-minimax-mcp","link":"#在-cursor-中配置-minimax-mcp","children":[]}]},{"level":2,"title":"在 Cursor 中使用 MCP 服务开发自己的应用","slug":"在-cursor-中使用-mcp-服务开发自己的应用","link":"#在-cursor-中使用-mcp-服务开发自己的应用","children":[{"level":3,"title":"选择对 MCP 兼容性好的模型","slug":"选择对-mcp-兼容性好的模型","link":"#选择对-mcp-兼容性好的模型","children":[]},{"level":3,"title":"允许自动流畅执行 MCP 工具调用","slug":"允许自动流畅执行-mcp-工具调用","link":"#允许自动流畅执行-mcp-工具调用","children":[]},{"level":3,"title":"获取城市景点的介绍","slug":"获取城市景点的介绍","link":"#获取城市景点的介绍","children":[]},{"level":3,"title":"按照类别整理景点介绍","slug":"按照类别整理景点介绍","link":"#按照类别整理景点介绍","children":[]},{"level":3,"title":"调用 Minimax 生成语音导览","slug":"调用-minimax-生成语音导览","link":"#调用-minimax-生成语音导览","children":[]},{"level":3,"title":"网页制作和部署","slug":"网页制作和部署","link":"#网页制作和部署","children":[]}]},{"level":2,"title":"网页效果的呈现","slug":"网页效果的呈现","link":"#网页效果的呈现","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"MCP&A2A前沿实战/03｜协议实战（上）：高德地图+MiniMax语音开发私域旅游小助手.md","filePath":"MCP&A2A前沿实战/03｜协议实战（上）：高德地图+MiniMax语音开发私域旅游小助手.md","lastUpdated":1795531178000}'),i={name:"MCP&A2A前沿实战/03｜协议实战（上）：高德地图+MiniMax语音开发私域旅游小助手.md"};function p(l,e,o,r,h,g){return n(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="_03-协议实战-上-高德地图-minimax语音开发私域旅游小助手" tabindex="-1">03 | 协议实战（上）：高德地图+MiniMax语音开发私域旅游小助手 <a class="header-anchor" href="#_03-协议实战-上-高德地图-minimax语音开发私域旅游小助手" aria-label="Permalink to &quot;03 | 协议实战（上）：高德地图+MiniMax语音开发私域旅游小助手&quot;">​</a></h1><p>你好，我是黄佳。</p><p>欢迎来到 MCP 协议实战的第一课。今天我们将结合 AI IDE（以 Cursor 为例），利用 MCP 服务快速搭建一个私人定制的“行旅小助手”系统。具体来说，我们会使用高德地图的地点推荐MCP 服务获取景点信息，再借助 Minimax 的语音生成 MCP 服务合成导览音频，并最终通过Agent 自动生成 HTML 页面，实现一个“西安旅游景点推介”的一条龙流程。</p><p>这是我们第一次动手实战，因此我特意选择了一个实操性非常强、而且又很实用、能看得见效果的 MCP 场景，我建议你跟着我一起一步一步的动起手来，感受一下大模型（MiniMax）开发、Cursor（AI Coder 或称为 AI IDE），以及 MCP 协议这三个技术栈相结合，构建一个 MVP级别的产品是多么容易。</p><p>如果你是一个产品设计者或开发者，这些强大的工具组合在一起，会让你觉得自己长出了三头六臂。这将是一次利用了多种 MCP 服务和最新大模型（gemini-2.5-pro-exp-03-25）以及Cursor Coding Agent 的 Vibe Code 新体验。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/1.png" alt=""></a></p><h2 id="私域旅游小助手开发流程" tabindex="-1">私域旅游小助手开发流程 <a class="header-anchor" href="#私域旅游小助手开发流程" aria-label="Permalink to &quot;私域旅游小助手开发流程&quot;">​</a></h2><p>这节课操作步骤较多，所以在开始实操之前，先给出你整个课程的流程：</p><ol><li><p>注册并配置高德地图 MCP 服务：获取城市与景点的推荐接口，实现地点信息检索。</p></li><li><p>注册并配置 Minimax 语音生成 MCP 服务：将文字转为语音，生成导览音频。</p></li><li><p>在 Cursor 中完成 MCP 服务的接入与调用配置：包括填写密钥、Model 兼容性设置、Agent自动运行配置等。</p></li><li><p>编写 Prompt 驱动 Agent：自动获取西安各类景点介绍，并按类别分条整理。</p></li><li><p>调用 Minimax 生成语音导览：将生成的景点介绍文本自动转为语音文件。</p></li><li><p>生成并部署 HTML 页面：利用 Agent 将整理好的文本输出为一个静态网页，并部署到线上。</p></li></ol><p>学完这节课之后，你将掌握在 AI IDE（Cursor）中如何集成第三方 MCP 服务的方法，还能快速搭建一个小而美的“城市景点介绍与导览”示例。</p><h2 id="使用高德开放平台的地图-mcp-服务" tabindex="-1">使用高德开放平台的地图 MCP 服务 <a class="header-anchor" href="#使用高德开放平台的地图-mcp-服务" aria-label="Permalink to &quot;使用高德开放平台的地图 MCP 服务&quot;">​</a></h2><p>高德地图（amap）官方提供了自己的 MCP 服务 sse 接口，要使用它的 MCP 服务，我们需要在这里登录高德开放平台，创建一个应用，并获取相应的 key。</p><h3 id="登录高德开放平台" tabindex="-1">登录高德开放平台 <a class="header-anchor" href="#登录高德开放平台" aria-label="Permalink to &quot;登录高德开放平台&quot;">​</a></h3><p>因为后面的个人实名认证步骤，需要使用支付宝认证，这里直接使用支付宝登录。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/3.png" alt=""></a></p><h3 id="注册为高德开放平台开发者" tabindex="-1">注册为高德开放平台开发者 <a class="header-anchor" href="#注册为高德开放平台开发者" aria-label="Permalink to &quot;注册为高德开放平台开发者&quot;">​</a></h3><p>下面，我们需要在这里注册自己为高德开放平台开发者。</p><p>进入个人控制台，会要求先完成开发者认证，这里选择个人开发者。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/4.png" alt=""></a></p><p>输入邮箱，填入验证码绑定邮箱，并完成个人实名认证。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/5.png" alt=""></a></p><p>系统提示，已经完成个人认证，你就成为了高德开放平台的开发者。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/6.png" alt=""></a></p><h3 id="获取高德服务密钥" tabindex="-1">获取高德服务密钥 <a class="header-anchor" href="#获取高德服务密钥" aria-label="Permalink to &quot;获取高德服务密钥&quot;">​</a></h3><p>下一步，是获取高德服务密钥的步骤。刚才提到，要获得密钥，需要先创建一个应用才行。</p><p>进入控制台，选择 应用管理 -&gt; 我的应用 -&gt; 创建新应用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/7.png" alt=""></a></p><p>应用类型选择“出行”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/8.png" alt=""></a></p><p>创建应用完成后，点击“添加 key”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/9.png" alt=""></a></p><p>填写“Key 名称”，服务平台选择 “Web 服务”，勾选已阅读协议，提交创建 key。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/10.png" alt=""></a></p><p>此时，key 就创建好了，可以把它复制下来，下一步在 Cursor 中配置 MCP 服务时会需要用到。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/11.png" alt=""></a></p><p>高德开放平台每月会有个人学习的减免额度，而且额度较大，因此不需要担心这个旅行助手在你出游过程中信息获取的费用问题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/12.png" alt=""></a></p><h3 id="在-cursor-中配置高德-mcp" tabindex="-1">在 Cursor 中配置高德 MCP <a class="header-anchor" href="#在-cursor-中配置高德-mcp" aria-label="Permalink to &quot;在 Cursor 中配置高德 MCP&quot;">​</a></h3><p>下面，进入 cursor，选择右上角 settings-&gt;MCP-&gt;Add new global MCP server。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/13.png" alt=""></a></p><p>复制下面的配置 json 到 mcp.json 中，这里需要用自己的 amap 的 key 来替换图中的占位符。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JSON</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;mcpServers&quot;: {</span></span>
<span class="line"><span>      &quot;amap-amap-sse&quot;: {</span></span>
<span class="line"><span>        &quot;url&quot;:   &quot;https://mcp.amap.com/sse?key=在高德开放平台获得的应用密钥&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/14.png" alt=""></a></p><p>之后我们返回 Cursor 设置界面查看 MCP 服务工具状态。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/15.png" alt=""></a></p><p>如果遇到任何问题，可以点击图右侧的绿色按钮重新 Enable 这些工具的功能。</p><h2 id="使用-minimax-大模型的语音服务" tabindex="-1">使用 MiniMax 大模型的语音服务 <a class="header-anchor" href="#使用-minimax-大模型的语音服务" aria-label="Permalink to &quot;使用 MiniMax 大模型的语音服务&quot;">​</a></h2><p>配置好了高德地图 MCP 服务之后，我们再来配置我们这个应用程序中要使用到的下一个MCP 服务—— MiniMax 提供的语音服务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/16.png" alt=""></a></p><p>MiniMax 可以提供即时生成的多模态数据。对于 MCP 产品，目前支持 stdio、sse 两种传输方式，即可以本地部署或平台托管（这里我将使用 ModelScope 魔搭平台进行托管），并且提供本地路径、远程 url 两种处理图片音视频等资源输入输出的方式。</p><h3 id="注册-minimax-开放平台" tabindex="-1">注册 Minimax 开放平台 <a class="header-anchor" href="#注册-minimax-开放平台" aria-label="Permalink to &quot;注册 Minimax 开放平台&quot;">​</a></h3><p>首先，根据你的情况，通过下面的链接之一，在 MiniMax 开放平台进行注册。</p><ul><li><p><a href="https://minimaxi.com" target="_blank" rel="noreferrer">https://minimaxi.com</a> 是 MiniMax 境内的官网</p></li><li><p><a href="https://minimax.io" target="_blank" rel="noreferrer">https://minimax.io</a> 是 MiniMax 境外的官网</p></li><li><p><a href="https://api.minimax.chat" target="_blank" rel="noreferrer">https://api.minimax.chat</a> 是境内服务的域名</p></li><li><p><a href="https://api.minimaxi.chat" target="_blank" rel="noreferrer">https://api.minimaxi.chat</a> 是境外服务的域名</p></li></ul><p>在这里注册 MiniMax 平台账号，并登录。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/17.png" alt=""></a></p><p>填写个人信息注册 MiniMax 平台</p><p>登录 MiniMax 平台后进入账户管理，创建接口密钥。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/18.png" alt=""></a></p><h3 id="在-modelscope-平台部署-minimax-sse" tabindex="-1">在 ModelScope 平台部署 Minimax sse <a class="header-anchor" href="#在-modelscope-平台部署-minimax-sse" aria-label="Permalink to &quot;在 ModelScope 平台部署 Minimax sse&quot;">​</a></h3><p>Minimax 官方在 ModelScope 平台提供了在线部署服务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/19.png" alt=""></a></p><p>分别填入：</p><ol><li><p><a href="https://api.minimax.chat" target="_blank" rel="noreferrer">https://api.minimax.chat</a></p></li><li><p>刚才在 Minimax 开放平台创建的 key 密钥</p></li><li><p>本地存放获取音视频的目录（有 stdio 和 url 两种模式，这里是必填项，先填一个本地存储生成音视频的目录）</p></li></ol><p>点击“连接”，即在 ModelScope 部署完成了托管服务，复制这里的完整 url。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/20.png" alt=""></a></p><h3 id="在-cursor-中配置-minimax-mcp" tabindex="-1">在 Cursor 中配置 Minimax MCP <a class="header-anchor" href="#在-cursor-中配置-minimax-mcp" aria-label="Permalink to &quot;在 Cursor 中配置 Minimax MCP&quot;">​</a></h3><p>好，下面我们需要在 Cursor 中配置 Minimax MCP，准备工作有两步。在 Model 平台托管的MiniMax-MCP 配置 URL，然后在 Minimax 开放平台账户管理中，查看并复制 GroupID。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/21.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/21.png" alt=""></a></p><ul><li>Minimax 开放平台中的 GroupID</li></ul><p>我们在 Cursor 的 MCP 配置文件中，填入上面两个信息，编辑后保存。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JSON</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;mcpServers&quot;: {</span></span>
<span class="line"><span>      &quot;MiniMax-MCP&quot;: {</span></span>
<span class="line"><span>        &quot;type&quot;:   &quot;sse&quot;,</span></span>
<span class="line"><span>        &quot;url&quot;:   &quot;https://mcp.api-inference.modelscope.cn/在ModelScope托管的url/s</span></span>
<span class="line"><span>        &quot;env&quot;: {</span></span>
<span class="line"><span>          &quot;MINIMAX_GROUP_ID&quot;:   &quot;1在账户信息里复制的GroupID一串数字&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      &quot;amap-amap-sse&quot;: {</span></span>
<span class="line"><span>        &quot;url&quot;:   &quot;https://mcp.amap.com/sse?key=在高德开放平台获得的应用密钥&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span></code></pre></div><p>这里填入刚刚复制的：</p><ol><li><p>ModelScope 平台托管的 Minimax 的 url</p></li><li><p>Minimax 个人的 GroupID</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/22.png" alt=""></a></p><p>回到 MCP 服务列表，打开这个服务的按钮打开，并刷新。等一会儿后，“Tools:”后面的“NoTools Available”会变成显示一系列的可用方法。如果一直显示“No Tools Available”，需要检查url 有没有完整复制，账户的 GroupID 和 key 是否正确。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/23.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/23.png" alt=""></a></p><h2 id="在-cursor-中使用-mcp-服务开发自己的应用" tabindex="-1">在 Cursor 中使用 MCP 服务开发自己的应用 <a class="header-anchor" href="#在-cursor-中使用-mcp-服务开发自己的应用" aria-label="Permalink to &quot;在 Cursor 中使用 MCP 服务开发自己的应用&quot;">​</a></h2><p>下面我们就要开始在 Cursor 中使用刚才配置好的两种 MCP 服务了，不过在这之前，我们还要再做一些 MCP 兼容性的设置。</p><h3 id="选择对-mcp-兼容性好的模型" tabindex="-1">选择对 MCP 兼容性好的模型 <a class="header-anchor" href="#选择对-mcp-兼容性好的模型" aria-label="Permalink to &quot;选择对 MCP 兼容性好的模型&quot;">​</a></h3><p>在 Cursor 提供的模型中，部分对 MCP 的兼容性还不好。这里推荐 Agent 执行能力、对 MCP反馈的整合能力都很强的模型：gemini-2.5-pro-exp-03-25。</p><p>在下图的 Cursor 设置中，调整备选的 Models。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/24.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/24.png" alt=""></a></p><h3 id="允许自动流畅执行-mcp-工具调用" tabindex="-1">允许自动流畅执行 MCP 工具调用 <a class="header-anchor" href="#允许自动流畅执行-mcp-工具调用" aria-label="Permalink to &quot;允许自动流畅执行 MCP 工具调用&quot;">​</a></h3><p>在 Feature 中找到 auto-run mode，为了让整个交互过程更加流畅，选择如下设置：</p><ul><li><p>勾选（3）“允许 Agent 默认不询问直接调用工具”，</p></li><li><p>不勾选（4）“阻止 Agent 自动运行 MCP 工具”</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/25.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/25.png" alt=""></a></p><p>好，上面就是 MCP 兼容性的设置，下面我们通过提示工程来实现所想要的功能。</p><h3 id="获取城市景点的介绍" tabindex="-1">获取城市景点的介绍 <a class="header-anchor" href="#获取城市景点的介绍" aria-label="Permalink to &quot;获取城市景点的介绍&quot;">​</a></h3><p>在 Cursor 的 Chat 对话框中，首先获取主要旅游景点信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据高德地图，获取西安市内的主要旅游景点信息|</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/26.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/26.png" alt=""></a></p><p>Cursor 作为 MCP Host，将通过 gemini-2.5-pro-exp-03-25 模型自动在对话中拉取调用 MCP工具，完成上面的任务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/27.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/27.png" alt=""></a></p><h3 id="按照类别整理景点介绍" tabindex="-1">按照类别整理景点介绍 <a class="header-anchor" href="#按照类别整理景点介绍" aria-label="Permalink to &quot;按照类别整理景点介绍&quot;">​</a></h3><p>下一步，再通过提示工程来按照类别，整理景点的介绍。</p><ul><li>帮我对这些景点分类，在百度百科上搜索相关的介绍，对每个景点生成一个详细的介绍，生动活泼有条理，并写</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/28.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/28.png" alt=""></a></p><p>可以看到 Agent 在努力地调用 MCP 服务，自行分条检索信息并汇总。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/29.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/29.png" alt=""></a></p><p>最后，Agent 会把生成的内容保存成新的 Markdown 文件，各景点信息已经分门别类整理到位。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/30.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/30.png" alt=""></a></p><h3 id="调用-minimax-生成语音导览" tabindex="-1">调用 Minimax 生成语音导览 <a class="header-anchor" href="#调用-minimax-生成语音导览" aria-label="Permalink to &quot;调用 Minimax 生成语音导览&quot;">​</a></h3><p>下面通过 @或者拖动到对话框的方式引用文件，并在对话中输入以下提示。</p><ul><li>生成各个景点的语音介绍，把得到的语音导览的链接放在标题的下方。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/31.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/31.png" alt=""></a></p><p>Agent 会识别、嵌入成功调用 MCP 并正确返回的 url，自动修改 markdown 文件。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/32.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/32.png" alt=""></a></p><p>由于刚刚生成的景点介绍文件较长，模型处理时可能会分段分次执行，每次返回解析 url 的方式可能不同，有时会在 MCP Call 中显示，有时会显式在输出中作为回复。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/33.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/33.png" alt=""></a></p><h3 id="网页制作和部署" tabindex="-1">网页制作和部署 <a class="header-anchor" href="#网页制作和部署" aria-label="Permalink to &quot;网页制作和部署&quot;">​</a></h3><p>好，现在你已经得到了每个景点的分类分条的文字和音频介绍，我们要用网页把内容呈现出来。这里我们让 Agent 按照给定的提示词生成网页并保存。</p><p>新建一个文件，叫 “prompt.md”，然后保存下面的内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Markdown</span></span>
<span class="line"><span>  #   页面提示词</span></span>
<span class="line"><span>  ## 网页风格指南</span></span>
<span class="line"><span>  你是一位国际顶尖的数字景区导览设计师和前端开发专家，擅长将传统景区介绍与现代网页设计完美融合，</span></span>
<span class="line"><span>  **可选设计风格：</span></span>
<span class="line"><span>  **1. **文化复古风格**</span></span>
<span class="line"><span>      适合历史文化类景区，使用仿古纸张纹理背景，搭配书法或篆刻风格的标题。色调以米黄、棕色等复古</span></span>
<span class="line"><span>  2. **现代简约风格**</span></span>
<span class="line"><span>      采用极简设计理念，主色调限制在2-3种，确保视觉统一性。排版注重网格系统，所有元素严格对齐。</span></span>
<span class="line"><span>  **必要页面组件：**</span></span>
<span class="line"><span>  1. **景区名称列表**：</span></span>
<span class="line"><span>    1. 景区名称</span></span>
<span class="line"><span>    2. 音频开始按钮：点击音频可以直接播放，播放时可以暂停，暂停的音频还可以继续播放</span></span>
<span class="line"><span>  2. **景区介绍**：</span></span>
<span class="line"><span>    1. 默认收缩，点击景区名称可弹出详细介绍</span></span>
<span class="line"><span>  ## 技术规范</span></span>
<span class="line"><span>  * 资源引用：</span></span>
<span class="line"><span>    * Tailwind CSS:   \`https://lf3-cdn-tos.bytecdntp.com/cdn/expire-1-M/tailwind</span></span>
<span class="line"><span>    * Font Awesome:   \`https://lf6-cdn-tos.bytecdntp.com/cdn/expire-100-M/font-a</span></span>
<span class="line"><span>    * 中文字体:   \`https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@40</span></span>
<span class="line"><span>    * Alpine.js:   \`https://unpkg.com/alpinejs@3.10.5/dist/cdn.min.js\`</span></span>
<span class="line"><span>  * 音频处理：</span></span>
<span class="line"><span>    * 使用HTML5   audio元素实现音频播放</span></span>
<span class="line"><span>    * 实现自定义播放控制按钮</span></span>
<span class="line"><span>    * 支持语音解说的暂停/继续功能，切换新音频直接打断正在播放的音频</span></span>
<span class="line"><span>  ## 输出要求</span></span>
<span class="line"><span>  * 提供一个完整的HTML文件，包含所有景区介绍内容</span></span>
<span class="line"><span>  * 代码应当简洁高效，注释充分，易于维护</span></span>
<span class="line"><span>  * 确保在不同尺寸的移动设备上都能良好展示</span></span>
<span class="line"><span>  * 所有文字内容使用中文输出</span></span>
<span class="line"><span>  * 确保文字的可读性，背景与文字有足够对比度</span></span></code></pre></div><p>最后一步，准备好提示词和刚刚的景点介绍内容文件，交给 Agent 生成 HTML 页面。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/34.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/34.png" alt=""></a></p><p>可以看到 Agent 帮我们快速生成了 HTML。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/35.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/35.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/36.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/36.png" alt=""></a></p><h2 id="网页效果的呈现" tabindex="-1">网页效果的呈现 <a class="header-anchor" href="#网页效果的呈现" aria-label="Permalink to &quot;网页效果的呈现&quot;">​</a></h2><p>下面，我们把这个页面上传到 youware.com，进行部署和展示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/37.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/37.png" alt=""></a></p><p>下面就是实际在线部署的页面。你可以通过这个链接来感受一下这个花费 2 个小时私人定制的旅游助理的效果。点击播放按钮，你将听到导游小助手甜美的播放各个旅游景点的介绍。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/38.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/38.jpeg" alt=""></a></p><p>怎么样，这是不是一次非常完美的、利用了多种 MCP 服务和最新大模型（gemini-2.5-pro-exp-03-25）以及 Cursor Agent 的 Vibe Coding 体验？</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li>ModelScope 中的 MCP 广场已经发布了海量的 MCP 服务，你可以根据自己的需要，按照我们这节课中介绍的步骤，完成更多个性化的、有特色的应用程序开发。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/39.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/03/39.png" alt=""></a></p><ol start="2"><li>这里我们通过纯提示工程完成了网页的开发和部署，没有写任何代码就生成了所需要的页面。请你通过代码（可以用 Cursor 或 Trae 等 AI Coder 辅助编码）进行自动化的工作，把上面的流程转换成一个有 UI 人机交互、有前端后端的应用程序，可以自动根据客户的需求来生成景点介绍，播放景点介绍的音频、甚至景点网站等。</li></ol><p>欢迎你在留言区和我交流讨论，如果这节课对你有启发，别忘了分享给身边更多朋友。</p>`,130)])])}const m=s(i,[["render",p]]);export{E as __pageData,m as default};
